UI_TEXT[LANGUAGES.UA] = UI_TEXT[LANGUAGES.UK];

/**
 * Selects Slavic/English plural form for an integer count.
 * Slavic languages (Ukrainian) use: 1 (not 11) -> one, 2-4 (not 12-14) -> few, else -> many.
 * @param {number} count
 * @param {string} lang
 * @param {{ one: string, few: string, many: string }} forms
 * @returns {string}
 */
export function selectPluralForm(count, lang = 'en', { one, few, many }) {
  const n = Math.abs(Math.floor(Number(count) || 0));
  const isUk = lang === 'uk' || lang === 'ua';
  if (!isUk) {
    return n === 1 ? one : many;
  }
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return few || many;
  return many;
}

export function formatWinsLabel(count, dict, lang = 'en') {
  const tpl = selectPluralForm(count, lang, {
    one: dict?.winSingular || '{n} Win',
    few: dict?.winsPaucal || dict?.winsShort || '{n} Wins',
    many: dict?.winsGenitive || dict?.winsShort || '{n} Wins'
  });
  return tpl.replace('{n}', String(count));
}

export function formatWordsLabel(count, dict, lang = 'en') {
  return selectPluralForm(count, lang, {
    one: dict?.wordsSingular || dict?.words || 'Word',
    few: dict?.words || 'Words',
    many: dict?.wordsGenitive || dict?.words || 'Words'
  });
}

export function formatVotesLabel(count, dict, lang = 'en') {
  return selectPluralForm(count, lang, {
    one: dict?.votesSingular || dict?.vote || 'Vote',
    few: dict?.votes || 'Votes',
    many: dict?.votesGenitive || dict?.votes || 'Votes'
  });
}

export function formatWordsNeededLabel(needed, dict, lang = 'en') {
  const isUk = lang === 'uk' || lang === 'ua';
  if (!isUk) {
    return needed === 1 ? '1 more word needed' : `${needed} ${dict?.wordsNeeded || 'more words needed'}`;
  }
  const unit = selectPluralForm(needed, lang, { one: 'слово', few: 'слова', many: 'слів' });
  return `Потрібно ще ${needed} ${unit}`;
}